package ro.leo.visual;
import android.content.*;import android.database.Cursor;import android.provider.ContactsContract;import android.provider.ContactsContract.CommonDataKinds.*;import java.util.*;
/** Exact provider rows; adding/removing one number never replaces the whole person. */
final class ContactBook {
 static final class Number {long id,raw;String value,label;}
 static ArrayList<Number> numbers(Context c,long contact){ArrayList<Number> out=new ArrayList<Number>();try(Cursor r=c.getContentResolver().query(Phone.CONTENT_URI,new String[]{Phone._ID,Phone.RAW_CONTACT_ID,Phone.NUMBER,Phone.TYPE,Phone.LABEL},Phone.CONTACT_ID+"=?",new String[]{""+contact},Phone.IS_PRIMARY+" DESC, "+Phone._ID+" ASC")){while(r!=null&&r.moveToNext()){Number n=new Number();n.id=r.getLong(0);n.raw=r.getLong(1);n.value=r.getString(2);n.label=Phone.getTypeLabel(c.getResources(),r.getInt(3),r.getString(4)).toString();out.add(n);}}return out;}
 static boolean valid(String number){return number!=null&&number.length()<=64&&number.matches("[+0-9*#()., \\-]{2,64}")&&number.matches(".*[0-9].*");}
 static void saveNumber(Context c,long raw,long data,String number,int type){if(!valid(number))throw new IllegalArgumentException();ContentValues v=new ContentValues();v.put(Phone.NUMBER,number.trim());v.put(Phone.TYPE,type);if(data<0){v.put(ContactsContract.Data.RAW_CONTACT_ID,raw);v.put(ContactsContract.Data.MIMETYPE,Phone.CONTENT_ITEM_TYPE);if(c.getContentResolver().insert(ContactsContract.Data.CONTENT_URI,v)==null)throw new IllegalStateException();}else if(c.getContentResolver().update(ContentUris.withAppendedId(ContactsContract.Data.CONTENT_URI,data),v,ContactsContract.Data.MIMETYPE+"=? AND "+ContactsContract.Data.RAW_CONTACT_ID+"=?",new String[]{Phone.CONTENT_ITEM_TYPE,""+raw})!=1)throw new IllegalStateException();}
 static void photo(Context c,long raw,byte[] bytes)throws Exception{ArrayList<ContentProviderOperation> ops=new ArrayList<ContentProviderOperation>();ops.add(ContentProviderOperation.newDelete(ContactsContract.Data.CONTENT_URI).withSelection(ContactsContract.Data.RAW_CONTACT_ID+"=? AND "+ContactsContract.Data.MIMETYPE+"=?",new String[]{""+raw,Photo.CONTENT_ITEM_TYPE}).build());if(bytes!=null){if(bytes.length>131072)throw new IllegalArgumentException();ops.add(ContentProviderOperation.newInsert(ContactsContract.Data.CONTENT_URI).withValue(ContactsContract.Data.RAW_CONTACT_ID,raw).withValue(ContactsContract.Data.MIMETYPE,Photo.CONTENT_ITEM_TYPE).withValue(Photo.PHOTO,bytes).withValue(ContactsContract.Data.IS_SUPER_PRIMARY,1).build());}c.getContentResolver().applyBatch(ContactsContract.AUTHORITY,ops);}
}
